from pathlib import Pathfrom typing import Dict, Optional, Unionimport loggingfrom . core import TxInOut, OutputFileManager, HRUManagerfrom . io import SWATParam, FileCIOfrom . run import SWATRunfrom . analysis import SWATAnalysislogger = logging.getLogger(__name__)class SWATProject:    """        >>> project = SWATProject(        ...     project_dir="D:/SWAT/my_project",        ...     swat_exe="D:/SWAT/swat2012.exe"        ... )        >>> project.update_parameters({'CN2': 75})        >>> project.run()        >>> df = project.output.read_reach()    """    def __init__(            self,            txinout_dir: Union[str, Path],            swat_exe:    Union[str, Path],            param_file:  Optional[str] = None    ):        self.txinout        = TxInOut(str(txinout_dir))        self.param_file     = SWATParam(param_file)        self.swat_exe       = SWATRun(swat_exe)        # ==========================================        self._hru_manager     = HRUManager(self.txinout, self.param_file)        self._file_cio        = FileCIO(self.txinout)        self._output_manager  = OutputFileManager(self.txinout)        #============================================        logger.info(f"SWAT Project initialized: {self.txinout}")        logger.info(f"Found {self.txinout.number_hru} HRUs in {self.txinout.number_sub} subbasins")    # ================ Read data =============================    def get_date_range(self, freq: str='D', year_start_non_skip: bool=False):        return self._file_cio.get_date_range_sim(freq, year_start_non_skip)    def statistic(self, sim, obs):        SWATAnalysis(self.txinout).calculate_statistics(obs, sim)    def read_params_values(self, param: list):        return self._hru_manager.read_muti_hru_param_values(param)    def run(self):        return self.swat_exe.run(self.txinout.directory)    def info(self):        """Print project information"""        print(f"TxtInOut: {self.txinout.directory}")        print("=" * 20)        print(f"SWAT Executable: {self.swat_exe}")        self.txinout.info()    def __repr__(self):        return (f"SWATProject '{self.txinout.directory}')', "                f"\n hrs={self.txinout.number_hru}, "                f"\n subs={self.txinout.number_sub})")    @property    def hru_manager(self):        return self._hru_manager    @property    def output_manager(self):        return self._output_manager